-- Rotten Blood party instances.
-- The physical rooms are generated by rotten_blood_instance_generator.lua.

-- Disabled: Rotten Blood has been restored to its original map levers and
-- shared boss rooms. Keep this implementation only as a reference so it can
-- be re-enabled deliberately in the future without affecting normal gameplay.
local INSTANCES_ENABLED = false
if not INSTANCES_ENABLED then
	RottenBloodInstances = nil
	return
end

RottenBloodInstances = RottenBloodInstances or {}

local manager = RottenBloodInstances
local ORIGIN = Position(32257, 34247, 7)
local SLOT_COUNT = 20
local GRID_COLUMNS = 10
local CELL_WIDTH = 28
local CELL_HEIGHT = 30
local FIGHT_TIME = 20 * 60
local LEAVE_TIME = 30
local THAIS_TEMPLE = Position(32369, 32241, 7)
local difficultyStorage = {
	murcion = 910200,
	ichgahal = 910201,
	chagorz = 910202,
	vemiath = 910203,
	bakragore = 910204,
}

local bosses = {
	murcion = {
		name = "Murcion",
		roomIndex = 0,
		size = { x = 17, y = 15 },
		bossOffset = { x = 8, y = 5 },
		entryOffset = { x = 9, y = 12 },
		exitOffset = { x = 9, y = 14 },
		exit = Position(33843, 31653, 13),
		cooldown = 20 * 60 * 60,
	},
	ichgahal = {
		name = "Ichgahal",
		roomIndex = 20,
		size = { x = 20, y = 17 },
		bossOffset = { x = 10, y = 7 },
		entryOffset = { x = 6, y = 15 },
		exitOffset = { x = 6, y = 17 },
		exit = Position(34101, 31681, 13),
		cooldown = 20 * 60 * 60,
	},
	chagorz = {
		name = "Chagorz",
		roomIndex = 40,
		size = { x = 17, y = 17 },
		bossOffset = { x = 9, y = 4 },
		entryOffset = { x = 9, y = 15 },
		exitOffset = { x = 9, y = 17 },
		exit = Position(33809, 31816, 13),
		cooldown = 20 * 60 * 60,
	},
	vemiath = {
		name = "Vemiath",
		roomIndex = 60,
		size = { x = 17, y = 17 },
		bossOffset = { x = 9, y = 5 },
		entryOffset = { x = 8, y = 14 },
		exitOffset = { x = 8, y = 17 },
		exit = Position(34116, 31879, 14),
		cooldown = 20 * 60 * 60,
	},
	bakragore = {
		name = "Bakragore",
		roomIndex = 80,
		size = { x = 19, y = 21 },
		bossOffset = { x = 10, y = 5 },
		entryOffset = { x = 10, y = 18 },
		exitOffset = { x = 10, y = 20 },
		exit = Position(34106, 32052, 13),
		cooldown = 68 * 60 * 60,
		requiresTaints = true,
	},
}

manager.active = manager.active or {}
manager.playerInstances = manager.playerInstances or {}
manager.nextId = manager.nextId or 0

local function positionAt(roomIndex, offset)
	local column = roomIndex % GRID_COLUMNS
	local row = math.floor(roomIndex / GRID_COLUMNS)
	return Position(
		ORIGIN.x + column * CELL_WIDTH + (offset.x or 0),
		ORIGIN.y + row * CELL_HEIGHT + (offset.y or 0),
		ORIGIN.z
	)
end

local function getMembers(leader)
	local members = { leader }
	local party = leader:getParty()
	if not party then
		return members
	end
	if party:getLeader() ~= leader then
		return nil, "Only the party leader can create a Rotten Blood instance."
	end
	for _, member in ipairs(party:getMembers()) do
		table.insert(members, member)
	end
	return members
end

local function findFreeSlot(bossKey)
	for slot = 1, SLOT_COUNT do
		local key = bossKey .. ":" .. slot
		if not manager.active[key] then
			return slot, key
		end
	end
	return nil
end

local function getWalkablePosition(center, index)
	local offsets = {
		{ 0, 0 },
		{ 1, 0 },
		{ -1, 0 },
		{ 0, 1 },
		{ 0, -1 },
	}
	local offset = offsets[((index - 1) % #offsets) + 1]
	local position = Position(center.x + offset[1], center.y + offset[2], center.z)
	local tile = Tile(position)
	if tile and tile:isWalkable() then
		return position
	end
	return center
end

local function cleanRoom(instance, removePlayers)
	local center = Position(
		math.floor((instance.from.x + instance.to.x) / 2),
		math.floor((instance.from.y + instance.to.y) / 2),
		instance.from.z
	)
	local rangeX = math.ceil((instance.to.x - instance.from.x) / 2) + 1
	local rangeY = math.ceil((instance.to.y - instance.from.y) / 2) + 1
	for _, creature in ipairs(Game.getSpectators(center, false, false, rangeX, rangeX, rangeY, rangeY)) do
		if creature:isPlayer() then
			if removePlayers then
				manager.playerInstances[creature:getId()] = nil
				creature:teleportTo(instance.returnPosition or instance.config.exit)
				creature:getPosition():sendMagicEffect(CONST_ME_TELEPORT)
			end
		elseif creature:isMonster() then
			creature:remove()
		end
	end
end

function manager.release(instanceId, delay)
	local instance = manager.active[instanceId]
	if not instance or instance.releasing then
		return
	end
	instance.releasing = true
	if instance.timeoutEvent then
		stopEvent(instance.timeoutEvent)
		instance.timeoutEvent = nil
	end
	addEvent(function(id)
		local current = manager.active[id]
		if not current then
			return
		end
		cleanRoom(current, true)
		manager.active[current.key] = nil
		manager.active[id] = nil
	end, (delay or 0) * 1000, instanceId)
end

function manager.leave(player)
	local instanceId = manager.playerInstances[player:getId()]
	local instance = instanceId and manager.active[instanceId] or nil
	if not instance then
		player:sendTextMessage(MESSAGE_EVENT_ADVANCE, "You are not inside a Rotten Blood instance.")
		return false
	end

	instance.players[player:getId()] = nil
	manager.playerInstances[player:getId()] = nil
	player:teleportTo(instance.config.exit, true)
	player:getPosition():sendMagicEffect(CONST_ME_TELEPORT)
	player:sendTextMessage(MESSAGE_EVENT_ADVANCE, "You left the " .. instance.config.name .. " instance.")

	if not next(instance.players) then
		manager.release(instance.id, 0)
	end
	return true
end

-- Removes only the bookkeeping link. Used when a player reaches an original
-- boss antechamber through a map portal after leaving a copied room.
function manager.detachPlayer(player)
	local playerId = player:getId()
	local instanceId = manager.playerInstances[playerId]
	if not instanceId then
		return false
	end
	local instance = manager.active[instanceId]
	if instance then
		instance.players[playerId] = nil
	end
	manager.playerInstances[playerId] = nil
	if instance and not next(instance.players) then
		manager.release(instance.id, 0)
	end
	return true
end

function manager.getByPosition(position)
	for id, instance in pairs(manager.active) do
		if type(id) == "number"
			and position.z == instance.from.z
			and position.x >= instance.from.x
			and position.x <= instance.to.x
			and position.y >= instance.from.y
			and position.y <= instance.to.y
		then
			return instance
		end
	end
	return nil
end

function manager.translate(templatePosition, reference)
	local position = reference.getPosition and reference:getPosition() or reference
	local instance = manager.getByPosition(position)
	if not instance then
		return templatePosition
	end
	local source = instance.sourceFrom
	return Position(
		instance.from.x + templatePosition.x - source.x,
		instance.from.y + templatePosition.y - source.y,
		instance.from.z + templatePosition.z - source.z
	)
end

function manager.start(leader, bossKey, difficulty)
	if bossKey == "bakragore" then
		leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, "Bakragore's Burden is available only through the original antechamber and lever.")
		return false
	end
	local config = bosses[bossKey]
	if not config then
		return false
	end
	local members, errorMessage = getMembers(leader)
	if not members then
		leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, errorMessage)
		return false
	end
	if #members > 5 then
		leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, "Rotten Blood instances support at most five players.")
		return false
	end

	local now = os.time()
	local maximumDifficulty = 25
	for _, member in ipairs(members) do
		if manager.playerInstances[member:getId()] then
			leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, member:getName() .. " is already in an instance.")
			return false
		end
		if member:getLevel() < 250 and member:getAccountType() < ACCOUNT_TYPE_GAMEMASTER then
			leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, member:getName() .. " must be level 250 or higher.")
			return false
		end
		if member:getBossCooldown(config.name:lower()) > now and member:getAccountType() < ACCOUNT_TYPE_GAMEMASTER then
			leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, member:getName() .. " still has a boss cooldown.")
			return false
		end
		if config.requiresTaints and (member:kv():scoped("rotten-blood-quest"):get("taints") or 0) < 4 then
			leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, member:getName() .. " needs all four Rotten Blood Taints.")
			return false
		end
		maximumDifficulty = math.min(maximumDifficulty, math.max(1, member:getStorageValue(difficultyStorage[bossKey])))
	end
	difficulty = math.max(0, math.min(maximumDifficulty, difficulty or 1))

	local slot, key = findFreeSlot(bossKey)
	if not slot then
		leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, "All " .. config.name .. " instances are occupied. Try again shortly.")
		return false
	end

	local roomIndex = config.roomIndex + slot - 1
	local roomFrom = positionAt(roomIndex, { x = 0, y = 0 })
	local instance = {
		id = manager.nextId + 1,
		key = key,
		slot = slot,
		bossKey = bossKey,
		config = config,
		difficulty = difficulty,
		from = roomFrom,
		to = Position(roomFrom.x + config.size.x, roomFrom.y + config.size.y, roomFrom.z),
		sourceFrom = ({
			murcion = Position(33000, 32360, 15),
			ichgahal = Position(32998, 32326, 15),
			chagorz = Position(33035, 32358, 15),
			vemiath = Position(33035, 32327, 15),
			bakragore = Position(33034, 32389, 15),
		})[bossKey],
		entry = positionAt(roomIndex, config.entryOffset),
		bossPosition = positionAt(roomIndex, config.bossOffset),
		players = {},
	}
	manager.nextId = instance.id
	manager.active[instance.id] = instance
	manager.active[key] = instance

	cleanRoom(instance, false)
	local boss = Game.createMonster(config.name, instance.bossPosition, true, true)
	if not boss then
		manager.active[instance.id] = nil
		manager.active[key] = nil
		leader:sendTextMessage(MESSAGE_EVENT_ADVANCE, "The instance could not create " .. config.name .. ".")
		return false
	end
	boss:setStorageValue("RottenBloodBossDifficulty", instance.difficulty)
	boss:setStorageValue("RottenBloodInstanceId", instance.id)
	boss:registerEvent("RottenBloodInstanceBossDeath")
	if instance.difficulty > 1 then
		local health = math.floor(boss:getMaxHealth() * (1 + (instance.difficulty - 1) * 0.08))
		boss:setMaxHealth(health)
		boss:setHealth(health)
	end

	for index, member in ipairs(members) do
		instance.players[member:getId()] = true
		manager.playerInstances[member:getId()] = instance.id
		member:setBossCooldown(config.name:lower(), now + config.cooldown)
		member:teleportTo(getWalkablePosition(instance.entry, index))
		member:getPosition():sendMagicEffect(CONST_ME_TELEPORT)
		member:sendTextMessage(MESSAGE_EVENT_ADVANCE, string.format("%s instance #%d started at difficulty %d.", config.name, slot, instance.difficulty))
	end

	instance.timeoutEvent = addEvent(function(instanceId)
		manager.release(instanceId, 0)
	end, FIGHT_TIME * 1000, instance.id)
	return true
end

local function showDifficultyWindow(player, bossKey)
	local config = bosses[bossKey]
	local members = getMembers(player)
	if not members then
		return
	end
	local maximum = 25
	for _, member in ipairs(members) do
		maximum = math.min(maximum, math.max(1, member:getStorageValue(difficultyStorage[bossKey])))
	end
	local window = ModalWindow({
		title = config.name .. " Difficulty",
		message = "Select the difficulty for this party instance.",
	})
	for difficulty = 0, maximum do
		local selected = difficulty
		window:addChoice("Difficulty " .. selected, function(currentPlayer, button)
			if button.name == "Start" then
				manager.start(currentPlayer, bossKey, selected)
			end
		end)
	end
	window:addButton("Start")
	window:addButton("Back", function(currentPlayer)
		manager.showBossWindow(currentPlayer)
	end)
	window:setDefaultEnterButton(0)
	window:setDefaultEscapeButton(1)
	window:sendToPlayer(player)
end

function manager.showBossWindow(player)
	local party = player:getParty()
	if party and party:getLeader() ~= player then
		player:sendTextMessage(MESSAGE_EVENT_ADVANCE, "Only the party leader can open the Rotten Blood queue.")
		return
	end
	local window = ModalWindow({
		title = "Rotten Blood Instances",
		message = "Choose a boss. Your complete party will be teleported automatically.",
	})
	for _, bossKey in ipairs({ "murcion", "ichgahal", "chagorz", "vemiath" }) do
		local selectedKey = bossKey
		local config = bosses[selectedKey]
		window:addChoice(config.name, function(currentPlayer, button)
			if button.name == "Select" then
				showDifficultyWindow(currentPlayer, selectedKey)
			end
		end)
	end
	window:addButton("Select")
	window:addButton("Close")
	window:setDefaultEnterButton(0)
	window:setDefaultEscapeButton(1)
	window:sendToPlayer(player)
end

local queue = TalkAction("!rotten")
function queue.onSay(player)
	manager.showBossWindow(player)
	return true
end
queue:groupType("normal")
queue:register()

local leave = TalkAction("!leave")
function leave.onSay(player)
	manager.leave(player)
	return true
end
leave:groupType("normal")
leave:register()

-- The copied portal items retain their appearance, but position-bound movement
-- events from the original rooms do not follow them. Bind each copied exit
-- position explicitly to the instance manager.
for bossKey, config in pairs(bosses) do
	for slot = 1, SLOT_COUNT do
		local roomIndex = config.roomIndex + slot - 1
		local exitPosition = positionAt(roomIndex, config.exitOffset)
		local instanceExit = MoveEvent()
		function instanceExit.onStepIn(creature)
			local player = creature:getPlayer()
			if player then
				manager.leave(player)
			end
			return true
		end
		instanceExit:position(exitPosition)
		instanceExit:type("stepin")
		instanceExit:register()
	end
end

local bossDeath = CreatureEvent("RottenBloodInstanceBossDeath")
function bossDeath.onDeath(creature)
	local instanceId = creature:getStorageValue("RottenBloodInstanceId")
	local instance = manager.active[instanceId]
	if not instance then
		return true
	end
	for playerId in pairs(instance.players) do
		local player = Player(playerId)
		if player then
			player:sendBannerType(BANNER_TYPE_BOSSDEFEATED)
			player:sendTextMessage(MESSAGE_EVENT_ADVANCE, "Boss defeated. The instance will close in " .. LEAVE_TIME .. " seconds.")
		end
	end
	instance.returnPosition = THAIS_TEMPLE
	manager.release(instanceId, LEAVE_TIME)
	return true
end
bossDeath:register()
